-- Controlled-pilot application layer. Applied to dedicated production project on 2026-09-01.
create table if not exists stabilis.pilot_accounts(organization_id uuid primary key references stabilis.organizations(id) on delete cascade,pilot_start date,pilot_status text not null default 'PLANNING' check(pilot_status in('PLANNING','ONBOARDING','SHADOW_MODE','ACTIVE','PAUSED','COMPLETED','CANCELLED')),data_completeness numeric(5,2) not null default 0 check(data_completeness between 0 and 100),analyst_owner uuid references stabilis.profiles(id) on delete set null,diagnostic_status text not null default 'NOT_STARTED',shadow_mode boolean not null default true,verification_eligible boolean not null default false,pilot_notes text,outcome_summary text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists stabilis.onboarding_progress(id uuid primary key default gen_random_uuid(),organization_id uuid not null references stabilis.organizations(id) on delete cascade,step_number integer not null check(step_number between 1 and 10),step_key text not null,completed boolean not null default false,payload jsonb not null default '{}'::jsonb,updated_by uuid references stabilis.profiles(id) on delete set null,updated_at timestamptz not null default now(),unique(organization_id,step_number));
create table if not exists stabilis.insight_feedback(id uuid primary key default gen_random_uuid(),organization_id uuid not null references stabilis.organizations(id) on delete cascade,finding_id uuid references stabilis.findings(id) on delete cascade,recommendation_id uuid references stabilis.recommendations(id) on delete cascade,profile_id uuid not null references stabilis.profiles(id) on delete cascade,useful_rating text check(useful_rating in('YES','PARTIALLY','NO')),recommendation_disposition text check(recommendation_disposition in('ACCEPTED','NEEDS_REVIEW','NOT_APPLICABLE')),comment text,created_at timestamptz not null default now(),check(finding_id is not null or recommendation_id is not null));
create table if not exists stabilis.operator_notes(id uuid primary key default gen_random_uuid(),organization_id uuid not null references stabilis.organizations(id) on delete cascade,location_id uuid references stabilis.locations(id) on delete cascade,author_id uuid not null references stabilis.profiles(id) on delete cascade,note_date date not null default current_date,context_type text not null default 'GENERAL' check(context_type in('GENERAL','LABOR','REVENUE','FORECAST','INVENTORY','FOOD','PURCHASING','ACTION','RESULT','DATA')),body text not null check(char_length(body) between 1 and 5000),created_at timestamptz not null default now());
create table if not exists stabilis.usage_events(id bigint generated always as identity primary key,organization_id uuid not null references stabilis.organizations(id) on delete cascade,profile_id uuid not null references stabilis.profiles(id) on delete cascade,event_name text not null,entity_type text,entity_id uuid,route text,created_at timestamptz not null default now());
create table if not exists stabilis.notification_preferences(organization_id uuid not null references stabilis.organizations(id) on delete cascade,profile_id uuid not null references stabilis.profiles(id) on delete cascade,high_risk_alerts boolean not null default true,sync_failures boolean not null default true,action_overdue boolean not null default true,report_ready boolean not null default true,verification_review boolean not null default true,email_enabled boolean not null default false,updated_at timestamptz not null default now(),primary key(organization_id,profile_id));
create index if not exists pilot_accounts_status_idx on stabilis.pilot_accounts(pilot_status,updated_at desc);create index if not exists onboarding_org_complete_idx on stabilis.onboarding_progress(organization_id,completed,step_number);create index if not exists operator_notes_org_location_date_idx on stabilis.operator_notes(organization_id,location_id,note_date desc);create index if not exists usage_events_org_created_idx on stabilis.usage_events(organization_id,created_at desc);create index if not exists opportunities_dashboard_idx on stabilis.opportunities(organization_id,counted_in_rollup,priority_score desc,created_at desc);create index if not exists actions_dashboard_idx on stabilis.actions(organization_id,status,due_date,updated_at desc);create index if not exists alerts_dashboard_idx on stabilis.alerts(organization_id,status,urgency,created_at desc);create index if not exists verified_values_dashboard_idx on stabilis.verified_values(organization_id,verification_status,verified_at desc);create index if not exists reports_release_idx on stabilis.reports(organization_id,release_status,generated_at desc);create index if not exists forecast_values_dashboard_idx on stabilis.forecast_values(organization_id,metric_name,forecast_date desc);
alter table stabilis.pilot_accounts enable row level security;alter table stabilis.onboarding_progress enable row level security;alter table stabilis.insight_feedback enable row level security;alter table stabilis.operator_notes enable row level security;alter table stabilis.usage_events enable row level security;alter table stabilis.notification_preferences enable row level security;
drop policy if exists pilot_read on stabilis.pilot_accounts;create policy pilot_read on stabilis.pilot_accounts for select using(stabilis.is_member(organization_id));drop policy if exists pilot_write on stabilis.pilot_accounts;create policy pilot_write on stabilis.pilot_accounts for all using(stabilis.is_internal_reviewer(organization_id)) with check(stabilis.is_internal_reviewer(organization_id));
drop policy if exists onboarding_read on stabilis.onboarding_progress;create policy onboarding_read on stabilis.onboarding_progress for select using(stabilis.is_member(organization_id));drop policy if exists onboarding_write on stabilis.onboarding_progress;create policy onboarding_write on stabilis.onboarding_progress for all using(stabilis.can_write_org(organization_id)) with check(stabilis.can_write_org(organization_id));
drop policy if exists feedback_read on stabilis.insight_feedback;create policy feedback_read on stabilis.insight_feedback for select using(stabilis.is_member(organization_id));drop policy if exists feedback_insert on stabilis.insight_feedback;create policy feedback_insert on stabilis.insight_feedback for insert with check(profile_id=auth.uid() and stabilis.is_member(organization_id));
drop policy if exists notes_read on stabilis.operator_notes;create policy notes_read on stabilis.operator_notes for select using(stabilis.is_member(organization_id) and(location_id is null or stabilis.can_access_location(organization_id,location_id)));drop policy if exists notes_insert on stabilis.operator_notes;create policy notes_insert on stabilis.operator_notes for insert with check(author_id=auth.uid() and stabilis.can_write_org(organization_id) and(location_id is null or stabilis.can_access_location(organization_id,location_id)));drop policy if exists notes_delete on stabilis.operator_notes;create policy notes_delete on stabilis.operator_notes for delete using(author_id=auth.uid() or stabilis.is_internal_reviewer(organization_id));
drop policy if exists usage_insert on stabilis.usage_events;create policy usage_insert on stabilis.usage_events for insert with check(profile_id=auth.uid() and stabilis.is_member(organization_id));drop policy if exists usage_read on stabilis.usage_events;create policy usage_read on stabilis.usage_events for select using(stabilis.is_internal_reviewer(organization_id));drop policy if exists notification_self on stabilis.notification_preferences;create policy notification_self on stabilis.notification_preferences for all using(profile_id=auth.uid() and stabilis.is_member(organization_id)) with check(profile_id=auth.uid() and stabilis.is_member(organization_id));
grant select on stabilis.pilot_accounts,stabilis.onboarding_progress,stabilis.insight_feedback,stabilis.operator_notes,stabilis.usage_events,stabilis.notification_preferences to authenticated;grant insert on stabilis.insight_feedback,stabilis.operator_notes,stabilis.usage_events to authenticated;grant select,insert,update on stabilis.onboarding_progress,stabilis.notification_preferences to authenticated;grant select,insert,update,delete on stabilis.pilot_accounts to authenticated;grant delete on stabilis.operator_notes to authenticated;grant usage on schema stabilis to authenticated;grant select on stabilis.organizations,stabilis.locations,stabilis.memberships,stabilis.score_results,stabilis.opportunities,stabilis.actions,stabilis.verified_values,stabilis.alerts,stabilis.reports,stabilis.forecast_runs,stabilis.forecast_values,stabilis.forecast_accuracy,stabilis.data_quality_runs,stabilis.data_quality_issues,stabilis.data_sources,stabilis.analysis_runs,stabilis.findings,stabilis.recommendations,stabilis.fact_sales,stabilis.fact_labor,stabilis.fact_inventory,stabilis.fact_food_cost,stabilis.fact_purchases to authenticated;
create or replace function public.stabilis_workspace_payload(p_organization_id uuid,p_location_id uuid default null) returns jsonb language plpgsql stable set search_path=public,stabilis,pg_temp as $$declare v_org text;v_role text;v_health numeric;v_dq numeric;v_fc numeric;v_modeled numeric;v_verified numeric;v_locations jsonb;v_opps jsonb;v_actions jsonb;v_alerts jsonb;v_reports jsonb;v_sources jsonb;v_dqi jsonb;v_notes jsonb;v_forecasts jsonb;v_pilot jsonb;v_onboarding jsonb;begin if auth.uid() is null or not stabilis.is_member(p_organization_id) then raise exception 'not authorized' using errcode='42501';end if;if p_location_id is not null and not stabilis.can_access_location(p_organization_id,p_location_id) then raise exception 'location not authorized' using errcode='42501';end if;select name into v_org from stabilis.organizations where id=p_organization_id;v_role:=stabilis.role_in_org(p_organization_id)::text;select score_value into v_health from stabilis.score_results where organization_id=p_organization_id and(p_location_id is null or location_id=p_location_id) and lower(score_name) like '%operator%health%' order by created_at desc limit 1;select score into v_dq from stabilis.data_quality_runs where organization_id=p_organization_id order by created_at desc limit 1;select confidence_score into v_fc from stabilis.forecast_runs where organization_id=p_organization_id order by generated_at desc limit 1;select coalesce(sum(coalesce(base_estimate,annualized_value,0)),0) into v_modeled from stabilis.opportunities where organization_id=p_organization_id and counted_in_rollup=true and upper(coalesce(opportunity_kind,'PRIMARY'))='PRIMARY' and(p_location_id is null or location_id=p_location_id);select coalesce(sum(verified_amount),0) into v_verified from stabilis.verified_values where organization_id=p_organization_id and verification_status='VERIFIED';select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into v_locations from(select l.id,l.code,l.name,l.market,l.region,l.service_model,null::numeric health,null::numeric sales_28d,null::numeric transactions_28d,null::numeric labor_pct_28d,(select fi.variance_value from stabilis.fact_inventory fi where fi.organization_id=l.organization_id and fi.location_id=l.id order by fi.count_date desc limit 1) inventory_variance,(select coalesce(sum(coalesce(o.base_estimate,o.annualized_value,0)),0) from stabilis.opportunities o where o.organization_id=l.organization_id and o.location_id=l.id and o.counted_in_rollup=true and upper(coalesce(o.opportunity_kind,'PRIMARY'))='PRIMARY') modeled_opportunity,(select count(*) from stabilis.actions a where a.organization_id=l.organization_id and a.location_id=l.id and upper(a.status) not in('COMPLETE','VERIFIED','REJECTED')) open_actions from stabilis.locations l where l.organization_id=p_organization_id and stabilis.can_access_location(p_organization_id,l.id) and(p_location_id is null or l.id=p_location_id) order by l.code limit 50)x;select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into v_opps from(select o.*,l.code location_code,coalesce(r.title,o.category||' operating opportunity') title,r.review_status recommendation_status from stabilis.opportunities o left join stabilis.locations l on l.id=o.location_id left join lateral(select title,review_status from stabilis.recommendations rr where rr.opportunity_id=o.id order by rr.created_at desc limit 1)r on true where o.organization_id=p_organization_id and(p_location_id is null or o.location_id=p_location_id) order by o.priority_score desc nulls last limit 50)x;select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into v_actions from(select a.*,l.code location_code from stabilis.actions a left join stabilis.locations l on l.id=a.location_id where a.organization_id=p_organization_id and(p_location_id is null or a.location_id=p_location_id) order by a.updated_at desc limit 50)x;select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into v_alerts from(select a.*,l.code location_code from stabilis.alerts a left join stabilis.locations l on l.id=a.location_id where a.organization_id=p_organization_id and(p_location_id is null or a.location_id=p_location_id) order by a.created_at desc limit 30)x;select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into v_reports from(select id,period,version,release_status,generated_at from stabilis.reports where organization_id=p_organization_id and release_status='CUSTOMER_RELEASED' order by generated_at desc limit 20)x;select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into v_sources from(select id,source_type,provider,name,status,last_success_at from stabilis.data_sources where organization_id=p_organization_id order by name)x;select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into v_dqi from(select q.*,l.code location_code from stabilis.data_quality_issues q left join stabilis.locations l on l.id=q.location_id where q.organization_id=p_organization_id and q.status in('OPEN','ACKNOWLEDGED','ACCEPTED_RISK') and(p_location_id is null or q.location_id=p_location_id) order by q.created_at desc limit 30)x;select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into v_notes from(select n.*,l.code location_code from stabilis.operator_notes n left join stabilis.locations l on l.id=n.location_id where n.organization_id=p_organization_id and(p_location_id is null or n.location_id=p_location_id) order by n.note_date desc limit 30)x;select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into v_forecasts from(select fv.*,l.code location_code,fr.methodology_version,fr.generated_at from stabilis.forecast_values fv join stabilis.forecast_runs fr on fr.id=fv.forecast_run_id left join stabilis.locations l on l.id=fv.location_id where fv.organization_id=p_organization_id and(p_location_id is null or fv.location_id=p_location_id) order by fv.forecast_date desc limit 50)x;select to_jsonb(x) into v_pilot from(select pilot_start,pilot_status,data_completeness,diagnostic_status,shadow_mode,verification_eligible,pilot_notes,outcome_summary,updated_at from stabilis.pilot_accounts where organization_id=p_organization_id)x;select jsonb_build_object('completed',coalesce(sum(case when completed then 1 else 0 end),0),'total',10,'steps',coalesce(jsonb_agg(jsonb_build_object('step',step_number,'key',step_key,'completed',completed,'updated_at',updated_at) order by step_number),'[]'::jsonb)) into v_onboarding from stabilis.onboarding_progress where organization_id=p_organization_id;return jsonb_build_object('generated_at',now(),'context',jsonb_build_object('organization_id',p_organization_id,'organization_name',v_org,'role',v_role,'location_id',p_location_id),'kpis',jsonb_build_object('operator_health',v_health,'modeled_opportunity',v_modeled,'verified_value',v_verified,'forecast_confidence',v_fc,'data_quality',v_dq),'locations',v_locations,'opportunities',v_opps,'actions',v_actions,'alerts',v_alerts,'reports',v_reports,'data_sources',v_sources,'data_quality_issues',v_dqi,'operator_notes',v_notes,'forecasts',v_forecasts,'pilot',coalesce(v_pilot,'{}'::jsonb),'onboarding',coalesce(v_onboarding,jsonb_build_object('completed',0,'total',10,'steps','[]'::jsonb)));end$$;revoke all on function public.stabilis_workspace_payload(uuid,uuid) from public,anon;grant execute on function public.stabilis_workspace_payload(uuid,uuid) to authenticated;
create or replace function public.stabilis_record_usage_event(p_organization_id uuid,p_event_name text,p_route text default null,p_entity_type text default null,p_entity_id uuid default null) returns bigint language plpgsql set search_path=public,stabilis,pg_temp as $$declare v bigint;begin if auth.uid() is null or not stabilis.is_member(p_organization_id) then raise exception 'not authorized' using errcode='42501';end if;insert into stabilis.usage_events(organization_id,profile_id,event_name,entity_type,entity_id,route) values(p_organization_id,auth.uid(),p_event_name,left(p_entity_type,80),p_entity_id,left(p_route,200)) returning id into v;return v;end$$;revoke all on function public.stabilis_record_usage_event(uuid,text,text,text,uuid) from public,anon;grant execute on function public.stabilis_record_usage_event(uuid,text,text,text,uuid) to authenticated;
create or replace function public.stabilis_add_operator_note(p_organization_id uuid,p_location_id uuid,p_context_type text,p_body text) returns uuid language plpgsql set search_path=public,stabilis,pg_temp as $$declare v uuid;begin if auth.uid() is null or not stabilis.can_write_org(p_organization_id) then raise exception 'not authorized' using errcode='42501';end if;if p_location_id is not null and not stabilis.can_access_location(p_organization_id,p_location_id) then raise exception 'location not authorized' using errcode='42501';end if;insert into stabilis.operator_notes(organization_id,location_id,author_id,context_type,body) values(p_organization_id,p_location_id,auth.uid(),upper(coalesce(p_context_type,'GENERAL')),p_body) returning id into v;insert into stabilis.audit_events(organization_id,actor_id,action,entity_type,entity_id,new_state) values(p_organization_id,auth.uid(),'OPERATOR_NOTE_CREATED','operator_note',v,jsonb_build_object('location_id',p_location_id,'context_type',p_context_type));return v;end$$;revoke all on function public.stabilis_add_operator_note(uuid,uuid,text,text) from public,anon;grant execute on function public.stabilis_add_operator_note(uuid,uuid,text,text) to authenticated;
create or replace function public.stabilis_update_onboarding_step(p_organization_id uuid,p_step_number integer,p_completed boolean,p_payload jsonb default '{}'::jsonb) returns void language plpgsql set search_path=public,stabilis,pg_temp as $$declare v_key text;begin if auth.uid() is null or not stabilis.can_write_org(p_organization_id) then raise exception 'not authorized' using errcode='42501';end if;v_key:=(array['ACCOUNT','ORGANIZATION','LOCATIONS','FISCAL_CALENDAR','OPERATING_TARGETS','DATA_CONNECTIONS','MAPPING','VALIDATION','FIRST_DIAGNOSTIC','COMMAND_CENTER'])[p_step_number];if v_key is null then raise exception 'invalid onboarding step';end if;insert into stabilis.onboarding_progress(organization_id,step_number,step_key,completed,payload,updated_by,updated_at) values(p_organization_id,p_step_number,v_key,p_completed,coalesce(p_payload,'{}'::jsonb),auth.uid(),now()) on conflict(organization_id,step_number) do update set completed=excluded.completed,payload=excluded.payload,updated_by=auth.uid(),updated_at=now();insert into stabilis.audit_events(organization_id,actor_id,action,entity_type,new_state) values(p_organization_id,auth.uid(),'ONBOARDING_STEP_UPDATED','onboarding_progress',jsonb_build_object('step',p_step_number,'completed',p_completed));end$$;revoke all on function public.stabilis_update_onboarding_step(uuid,integer,boolean,jsonb) from public,anon;grant execute on function public.stabilis_update_onboarding_step(uuid,integer,boolean,jsonb) to authenticated;
